// Carrot Revolt Labs · Upscale & Detail Lab · stages, steps and live checklists.
// It runs on the ComfyUI Lab interface (../comfyui/app.js) and adds its own nodes and detail simulator (./nodes.js).
import { defaultGraph, makeNode, makeLink, connect } from '../comfyui/engine.js';
import { summary, findRecipe as find, UPSCALERS } from './nodes.js';
export const L = (en, ca, es) => ({ en, ca, es });

export const META = { key: 'carrot-revolt-comfy-upscale:', title: 'Upscale & Detail Lab', label: 'GENERATIVE IMAGE / COMFYUI · 03' };

/* ── Graph helpers ── */
const N = (g, type) => g.nodes.filter(n => n.type === type && n.mode === 0);
const into = (g, id, input) => g.links.find(l => l.to === id && l.input === input);
const from = (g, id, input) => { const l = into(g, id, input); return l ? g.nodes.find(n => n.id === l.from) : null; };
const goal = (text, test, optional = false) => ({ text, test, optional });
const add = (g, ...nodes) => { g.nodes.push(...nodes); return g; };
const wire = (g, list) => { for (const l of list) connect(g, makeLink(...l)); return g; };
const set = (g, id, k, v) => { g.nodes.find(n => n.id === id).widgets[k] = v; return g; };
const move = (g, id, x, y) => { const n = g.nodes.find(n => n.id === id); n.x = x; n.y = y; return g; };
const out = c => c.history.filter(h => h.outW);
const ran = (c, f) => out(c).some(f);
const PROMPT = 'a woman on the beach, sunset, detailed', WIDE = 'a woman on the beach, wide shot, sunset, detailed';
const sampler2 = (id, x, y, denoise) => makeNode('KSampler', x, y, { denoise, control_after_generate: 'fixed' }, id);

/* ── Starters and solutions ── */
const G = {
  base: (text = PROMPT, size = 512) => { const g = defaultGraph(); set(g, 'pos', 'text', text); set(g, 'neg', 'text', 'blurry, text, watermark'); set(g, 'sampler', 'control_after_generate', 'fixed'); set(g, 'latent', 'width', size); set(g, 'latent', 'height', size); return g; },
  // Decode → [nodes] → Save, in a row after VAE Decode.
  chain: (g, nodes, start = 'decode') => { let prev = start, x = 1460; for (const n of nodes) { n.x = x; n.y = n.y || 186; add(g, n); wire(g, [[prev, 0, n.id, 'image']]); prev = n.id; x += 330; } move(g, 'save', x, 189); wire(g, [[prev, 0, 'save', 'images']]); return g; },
  scaleBy: (method = 'lanczos', f = 4) => G.chain(G.base(), [makeNode('ImageScaleBy', 0, 0, { upscale_method: method, scale_by: f }, 'up')]),
  model: (name = '4x-UltraSharp.pth') => { const g = G.chain(G.base(), [makeNode('ImageUpscaleWithModel', 0, 0, {}, 'ups')]); add(g, makeNode('UpscaleModelLoader', 1209, 330, { model_name: name }, 'uml')); return wire(g, [['uml', 0, 'ups', 'upscale_model']]); },
  modelHalf: () => { const g = G.chain(G.base(), [makeNode('ImageUpscaleWithModel', 0, 0, {}, 'ups'), makeNode('ImageScaleBy', 0, 0, { upscale_method: 'lanczos', scale_by: .5 }, 'down')]); add(g, makeNode('UpscaleModelLoader', 1209, 330, {}, 'uml')); return wire(g, [['uml', 0, 'ups', 'upscale_model']]); },
  latentRaw: (f = 2) => { const g = G.base(); add(g, makeNode('LatentUpscaleBy', 1209, 400, { scale_by: f }, 'lup')); move(g, 'decode', 1560, 188); move(g, 'save', 1800, 189); return wire(g, [['sampler', 0, 'lup', 'samples'], ['lup', 0, 'decode', 'samples']]); },
  hires: (d = .5, f = 2) => { const g = G.latentRaw(f); add(g, sampler2('s2', 1560, 186, d)); move(g, 'decode', 1920, 188); move(g, 'save', 2160, 189); return wire(g, [['ckpt', 0, 's2', 'model'], ['pos', 0, 's2', 'positive'], ['neg', 0, 's2', 'negative'], ['lup', 0, 's2', 'latent_image'], ['s2', 0, 'decode', 'samples']]); },
  pixelHires: (d = .35) => {
    const g = G.base(); add(g, makeNode('UpscaleModelLoader', 1209, 330, {}, 'uml'), makeNode('ImageUpscaleWithModel', 1460, 186, {}, 'ups'), makeNode('ImageScaleBy', 1460, 330, { upscale_method: 'lanczos', scale_by: .5 }, 'down'), makeNode('VAEEncode', 1790, 330, {}, 'enc'), sampler2('s2', 2040, 186, d), makeNode('VAEDecode', 2400, 188, {}, 'dec2'));
    move(g, 'save', 2650, 189);
    return wire(g, [['uml', 0, 'ups', 'upscale_model'], ['decode', 0, 'ups', 'image'], ['ups', 0, 'down', 'image'], ['down', 0, 'enc', 'pixels'], ['ckpt', 2, 'enc', 'vae'], ['ckpt', 0, 's2', 'model'], ['pos', 0, 's2', 'positive'], ['neg', 0, 's2', 'negative'], ['enc', 0, 's2', 'latent_image'], ['s2', 0, 'dec2', 'samples'], ['ckpt', 2, 'dec2', 'vae'], ['dec2', 0, 'save', 'images']]);
  },
  usdu: (w = {}, src = G.base()) => {
    const g = src, img = g.nodes.some(n => n.id === 'dec2') ? 'dec2' : g.nodes.some(n => n.id === 'fd') ? 'fd' : 'decode', x = Math.max(...g.nodes.map(n => n.x)) + 20;
    g.links = g.links.filter(l => l.to !== 'save');
    if (!g.nodes.some(n => n.id === 'uml')) add(g, makeNode('UpscaleModelLoader', x - 300, 560, {}, 'uml'));
    add(g, makeNode('UltimateSDUpscale', x, 120, { upscale_by: 4, denoise: .3, ...w }, 'usdu')); move(g, 'save', x + 380, 189);
    return wire(g, [[img, 0, 'usdu', 'image'], ['ckpt', 0, 'usdu', 'model'], ['pos', 0, 'usdu', 'positive'], ['neg', 0, 'usdu', 'negative'], ['ckpt', 2, 'usdu', 'vae'], ['uml', 0, 'usdu', 'upscale_model'], ['usdu', 0, 'save', 'images']]);
  },
  usduTile: (d = .5) => {
    const g = G.usdu({ denoise: d }); add(g, makeNode('ControlNetLoader', 1209, 760, { control_net_name: 'control_v11f1e_sd15_tile.pth' }, 'cnl'), makeNode('ControlNetApplyAdvanced', 1460, 620, { strength: .8 }, 'cn'));
    return wire(g, [['pos', 0, 'cn', 'positive'], ['neg', 0, 'cn', 'negative'], ['cnl', 0, 'cn', 'control_net'], ['decode', 0, 'cn', 'image'], ['cn', 0, 'usdu', 'positive'], ['cn', 1, 'usdu', 'negative']]);
  },
  detailer: (w = {}, src = G.base(WIDE)) => {
    const g = src, img = g.nodes.some(n => n.id === 's2') ? 'decode' : 'decode';
    g.links = g.links.filter(l => l.to !== 'save'); const x = Math.max(...g.nodes.filter(n => n.id !== 'save').map(n => n.x)) + 350;
    add(g, makeNode('UltralyticsDetectorProvider', x - 330, 560, {}, 'det'), makeNode('FaceDetailer', x, 120, { denoise: .45, ...w }, 'fd')); move(g, 'save', x + 380, 189);
    return wire(g, [[img, 0, 'fd', 'image'], ['ckpt', 0, 'fd', 'model'], ['ckpt', 1, 'fd', 'clip'], ['ckpt', 2, 'fd', 'vae'], ['pos', 0, 'fd', 'positive'], ['neg', 0, 'fd', 'negative'], ['det', 0, 'fd', 'bbox_detector'], ['fd', 0, 'save', 'images']]);
  },
  full: () => G.usdu({ denoise: .3 }, G.detailer({}, G.hires(.5))),
  fullStart: () => G.hires(.5),
};

/* ── History: what the checklists read ── */
export const findRecipe = find;
export function outputExtra(img) { const s = summary(img); return { ...s, w: s.outW, h: s.outH }; }
const pct = v => `${Math.round(v * 100)}%`;
export function resultExtra(h) {
  if (!h.outW) return '';
  const row = (k, v) => `<dt>${k}</dt><dd>${v}</dd>`;
  const edge = { clean: 'clean', soft: 'soft (blurred)', blocky: 'blocky (latent / nearest)', sharp: 'sharp but flat', waxy: 'smooth, waxy' }[h.edge] || h.edge;
  return `<dl class="q-dl">${row('real detail', pct(h.detail))}${row('texture', pct(h.tex))}${row('edges', edge)}${h.faceQ !== null ? row('face', `${pct(h.faceQ)} · ${h.facePx}px`) : ''}${h.dup > 1 ? row('copies', h.dup) : ''}${h.ghosts ? row('tile ghosts', h.ghosts) : ''}${h.seams ? row('tile seams', pct(h.seams)) : ''}${h.detected !== null && h.detailer ? row('faces found', h.detected) : ''}</dl>`;
}
const passIn = (h, lo, hi) => h.passes.some(p => p.d >= lo && p.d <= hi && p.W > 512);

