  ImageScaleBy: { short: L('Resizes by a factor.', 'Redimensiona per un factor.', 'Redimensiona por un factor.'), long: L('Interpolation only: ×4 gives 16 times more pixels and exactly the same detail, blurred. Great for going <i>down</i> (0.5 after a ×4 model) or for a final fit.', 'Només interpolació: ×4 dona 16 vegades més píxels i exactament el mateix detall, borrós. Perfecte per <i>baixar</i> (0.5 després d’un model ×4) o per a un ajust final.', 'Solo interpolación: ×4 da 16 veces más píxeles y exactamente el mismo detalle, borroso. Perfecto para <i>bajar</i> (0.5 después de un modelo ×4) o para un ajuste final.'), widgets: { upscale_method: L('lanczos or bicubic for photos', 'lanczos o bicubic per a fotos', 'lanczos o bicubic para fotos'), scale_by: L('the factor (0.5 = half)', 'el factor (0.5 = la meitat)', 'el factor (0.5 = la mitad)') } },
  LatentUpscale: { short: L('Resizes the latent to an exact size.', 'Redimensiona el latent a una mida exacta.', 'Redimensiona el latente a un tamaño exacto.'), long: L('The latent is 8× smaller than the picture: resizing it makes blocks. It only works followed by a KSampler with enough denoise.', 'El latent és 8× més petit que la imatge: redimensionar-lo fa blocs. Només funciona seguit d’un KSampler amb prou denoise.', 'El latente es 8× más pequeño que la imagen: redimensionarlo hace bloques. Solo funciona seguido de un KSampler con suficiente denoise.') },
