  UltralyticsDetectorProvider: { short: L('Loads a YOLO detector (faces, hands, people).', 'Carrega un detector YOLO (cares, mans, persones).', 'Carga un detector YOLO (caras, manos, personas).'), long: L('Impact Pack. bbox models find boxes, segm models find shapes. face_yolov8 for faces, hand_yolov8 for hands.', 'Impact Pack. Els models bbox troben requadres, els segm troben formes. face_yolov8 per a cares, hand_yolov8 per a mans.', 'Impact Pack. Los modelos bbox encuentran recuadros, los segm encuentran formas. face_yolov8 para caras, hand_yolov8 para manos.') },
  FaceDetailer: { short: L('Finds faces and redraws them at full size.', 'Troba cares i les redibuixa a mida completa.', 'Encuentra caras y las redibuja a tamaño completo.'), long: L('Impact Pack. Detect → crop around each face → scale the crop to guide_size → inpaint it → paste it back. A face of 30 pixels gets the model’s full attention. The same idea as crop and stitch, automatic.', 'Impact Pack. Detecta → retalla al voltant de cada cara → escala el retall a guide_size → hi fa inpaint → el torna a enganxar. Una cara de 30 píxels rep tota l’atenció del model. La mateixa idea que el crop and stitch, automàtica.', 'Impact Pack. Detecta → recorta alrededor de cada cara → escala el recorte a guide_size → le hace inpaint → lo vuelve a pegar. Una cara de 30 píxeles recibe toda la atención del modelo. La misma idea que el crop and stitch, automática.'), widgets: { guide_size: L('the size the face is redrawn at', 'la mida a què es redibuixa la cara', 'el tamaño al que se redibuja la cara'), denoise: L('0.35–0.5: fixes without changing who it is', '0.35–0.5: arregla sense canviar qui és', '0.35–0.5: arregla sin cambiar quién es'), bbox_threshold: L('minimum confidence; lower it if small faces are missed', 'confiança mínima; baixa-la si no troba cares petites', 'confianza mínima; bájala si no encuentra caras pequeñas'), bbox_crop_factor: L('context around the face (3 = 3× the box)', 'context al voltant de la cara (3 = 3× el requadre)', 'contexto alrededor de la cara (3 = 3× el recuadro)'), feather: L('soft border of the pasted face', 'vora suau de la cara enganxada', 'borde suave de la cara pegada'), drop_size: L('ignore faces smaller than this (px)', 'ignora cares més petites que això (px)', 'ignora caras más pequeñas que esto (px)') } },
