        how: [L('<b>Load ControlNet Model</b>: control_v11f1e_sd15_tile.pth.', '<b>Load ControlNet Model</b>: control_v11f1e_sd15_tile.pth.', '<b>Load ControlNet Model</b>: control_v11f1e_sd15_tile.pth.'), L('<b>Apply ControlNet</b>: prompts in, image = the 512 picture, strength 0.8. Its positive and negative → Ultimate SD Upscale.', '<b>Apply ControlNet</b>: entren els prompts, image = la imatge de 512, strength 0.8. El seu positive i negative → Ultimate SD Upscale.', '<b>Apply ControlNet</b>: entran los prompts, image = la imagen de 512, strength 0.8. Su positive y negative → Ultimate SD Upscale.'), L('denoise <b>0.5</b>, run.', 'denoise <b>0.5</b>, executa.', 'denoise <b>0.5</b>, ejecuta.')],
