        starter: () => G.base(WIDE), solution: () => G.detailer(),
        goals: [goal(L('Saw the small face melt', 'Has vist com es fon la cara petita', 'Has visto cómo se funde la cara pequeña'), (g, c) => ran(c, h => h.wide && !h.detailer && h.faceQ !== null && h.faceQ < .4), true), goal(L('FaceDetailer gets a face detector', 'FaceDetailer rep un detector de cares', 'FaceDetailer recibe un detector de caras'), g => N(g, 'FaceDetailer').some(n => from(g, n.id, 'bbox_detector')?.widgets.model_name?.includes('face'))), goal(L('A face found and redrawn', 'Una cara trobada i redibuixada', 'Una cara encontrada y redibujada'), (g, c) => ran(c, h => h.detailer && h.detected > 0 && h.faceQ >= .75))],
