        how: [L('FaceDetailer › denoise <b>0.8</b>, run: who is that?', 'FaceDetailer › denoise <b>0.8</b>, executa: qui és aquesta?', 'FaceDetailer › denoise <b>0.8</b>, ejecuta: ¿quién es esa?'), L('denoise 0.45, bbox_threshold <b>0.8</b>, run: “faces found: 0”.', 'denoise 0.45, bbox_threshold <b>0.8</b>, executa: “faces found: 0”.', 'denoise 0.45, bbox_threshold <b>0.8</b>, ejecuta: “faces found: 0”.'), L('Back to threshold 0.5 and denoise 0.35–0.5.', 'Torna a threshold 0.5 i denoise 0.35–0.5.', 'Vuelve a threshold 0.5 y denoise 0.35–0.5.')],
